// Visual editorial por área: apenas decorativo; nunca substitui o texto da tarefa.
function artKey(t){
 const s=((t.title||'')+' '+(t.room||'')).toLocaleLowerCase('pt-PT');
 if(/gato|planta tóxica|plantas potencialmente/.test(s))return 'botanical';
 if(/sifão|canaliza|odor|cheiro|esgoto|torneira|lava-loiça|poço/.test(s))return 'plumbing';
 if(/eletric|cctv|câmara|videoporteiro|cabo|quadro|luminária|iluminação/.test(s))return 'electric';
 if(/jardim|terreno|alpendre|terraço|limoeiro|mato|árvore|raiz/.test(s))return 'outdoor';
 if(/lavandaria|roupa|estendal|cordas/.test(s))return 'laundry';
 if(/cozinha|café|bebidas|louça/.test(s))return 'coffee';
 if(/wc |banho|duche|lavatório|piaçaba|higiénico/.test(s))return 'bath';
 if(/escritório|secretária|impressora|monitor|cadeira/.test(s))return 'office';
 if(/limpeza|aspirador|limpar|pó|chão/.test(s))return 'cleaning';
 if(/caixote|armário|arrumar|organiza|móvel|rodapé|guardar/.test(s))return 'storage';
 return 'general';
}
