function visualRooms(active){
 const counts={};active.forEach(t=>{const r=t.room||'Geral';counts[r]=(counts[r]||0)+1;});
 const recommended=['Cozinha','Exterior','Instalações técnicas','Lavandaria','Escritório','Organização geral','WC completo','WC suite'];
 const names=[...recommended.filter(r=>counts[r]),...Object.keys(counts).filter(r=>!recommended.includes(r)).sort((a,b)=>counts[b]-counts[a])].slice(0,4);
 return names.map(room=>`<button class="room-tile" type="button" data-action="open-room" data-room="${esc(room)}"><span class="room-art art-${esc(roomIcons[room]||'general')}" aria-hidden="true"></span><span class="room-tile-meta"><strong>${esc(room)}</strong><small>${counts[room]} ${counts[room]===1?'tarefa':'tarefas'}</small></span><span class="room-arrow" aria-hidden="true">↗</span></button>`).join('');
}
