function demoApi(p,method,b){if(p==='/api/bootstrap')return {setup:false,user:store.user};if(p==='/api/state')return store;
 if(p==='/api/logout')return {ok:true};if(p==='/api/finance')return {finance:store.finance||{accounts:[],transactions:[],budgets:[],goals:[]}};if(p.startsWith('/api/finance/')&&method==='POST'){store.finance=store.finance||{accounts:[],transactions:[],budgets:[],goals:[]};const segment=p.split('/')[3],list={accounts:'accounts',transactions:'transactions',budgets:'budgets',goals:'goals'}[segment];if(list){const data={...b,id:'demo-fin-'+Date.now()};store.finance[list].push(data);persistDemo();return {[{accounts:'account',transactions:'transaction',budgets:'budget',goals:'goal'}[segment]]:data};}}if(p==='/api/settings'&&method==='PATCH'){store.settings=b;persistDemo();return {settings:b};}if(p==='/api/export')return store;if(p==='/api/shopping'&&method==='POST'){const item={...b,id:'si'+Date.now(),purchased:false,createdBy:store.user.id};store.shopping=shopping().concat(item);persistDemo();return {item};}const sm=p.match(/^\/api\/shopping\/([^/]+)$/);if(sm){const it=shopping().find(x=>x.id===sm[1]);if(method==='PATCH'&&it)Object.assign(it,b);if(method==='DELETE')store.shopping=shopping().filter(x=>x.id!==sm[1]);persistDemo();return {item:it};}if(p==='/api/worklogs'&&method==='POST'){const entry={...b,id:'wl'+Date.now(),userId:b.userId||store.user.id};store.workLogs=workLogs().concat(entry);persistDemo();return {entry};}
 if(p==='/api/tasks'&&method==='POST'){const t={id:'d'+Date.now()+Math.random().toString().slice(2),createdAt:new Date().toISOString(),...b};store.tasks.push(t);persistDemo();return {task:t};}
 const m=p.match(/^\/api\/tasks\/([^/]+)(\/complete)?$/);if(m){let t=tasks().find(x=>x.id===m[1]);if(!t)throw Error('Tarefa não encontrada.');if(m[2]){store.history.push({id:'h'+Date.now(),title:t.title,at:new Date().toISOString(),by:store.user.id,kind:t.kind,assignedTo:t.assignedTo});if(t.kind==='routine'&&t.repeat!=='none'){t.status='todo';t.dueDate=nextDemoDate(t.dueDate,t.repeat);t.suggested=false;}else t.status='done';}else if(method==='PATCH'){Object.assign(t,b);}else if(method==='DELETE'){store.tasks=tasks().filter(x=>x.id!==t.id);}persistDemo();return {task:t};}
 if(p==='/api/people'&&method==='POST'){store.people.push({id:'u'+Date.now(),name:b.name,username:b.username,role:b.role||'resident'});persistDemo();return {people:store.people};}const roleMatch=p.match(/^\/api\/people\/([^/]+)\/role$/);if(roleMatch&&method==='PATCH'){const u=store.people.find(x=>x.id===roleMatch[1]);if(u)u.role=b.role;persistDemo();return {people:store.people};}
 return {ok:true};}
function nextDemoDate(iso,repeat){let d=iso?new Date(iso+'T12:00:00Z'):new Date();const step=()=>{if(repeat==='monthly')d.setUTCMonth(d.getUTCMonth()+1);else d.setUTCDate(d.getUTCDate()+({daily:1,weekly:7,biweekly:14}[repeat]||7));};step();while(d<new Date())step();return d.toISOString().slice(0,10);}
