function renderAuth(mode,err=''){const isSetup=mode==='setup';app.innerHTML=`<div class="auth-layout"><section class="auth-aside"><div class="brand brand-primary"><img class="brand-primary-logo" src="logo-primary-light.svg" alt="CASA EM DIA" /></div><div><h1>A casa em ordem.<br/><em>Ao vosso ritmo.</em></h1><p>Um espaço comum para organizar pendências, dividir tarefas e celebrar o que já está feito.</p></div><small>O teu espaço, os teus dados, o teu ritmo.</small></section><section class="auth-form"><div class="auth-inner"><img class="auth-mobile-logo" src="logo-primary-dark.svg" alt="Casa em Dia" /><div class="eyebrow">CASA EM DIA · ${isSetup?'PRIMEIRO ACESSO':'BEM-VINDO DE VOLTA'}</div><h2>${isSetup?'Vamos preparar a tua casa.':'Entrar na tua casa.'}</h2><p>${isSetup?'Cria a primeira conta, que poderá convidar as restantes pessoas da casa.':'Inicia sessão para veres e atualizares as tarefas partilhadas.'}</p><form id="auth-form">${isSetup?`<div class="field"><label>O teu nome</label><input autocomplete="name" name="name" required minlength="2" placeholder="Como queres ser identificado"/></div>`:''}<div class="field"><label>Nome de utilizador</label><input autocomplete="username" name="username" required minlength="3" placeholder="Ex.: carlos"/></div><div class="field"><label>Palavra-passe</label><input type="password" autocomplete="${isSetup?'new-password':'current-password'}" name="password" minlength="${isSetup?10:1}" required placeholder="${isSetup?'Mínimo de 10 caracteres':'A tua palavra-passe'}"/></div><button class="button primary" type="submit">${isSetup?'Criar casa e entrar':'Entrar na aplicação'} ${ico('chevron')}</button><div class="auth-message" id="auth-error">${esc(err)}</div></form></div></section></div>`;
 const f=$('#auth-form');f.addEventListener('submit',async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(f));const submit=f.querySelector('button');submit.disabled=true;try{await api(isSetup?'/api/setup':'/api/login','POST',data);await load();render();}catch(e){$('#auth-error').textContent=e.message;}finally{submit.disabled=false;}});
}
